-- V90.q Material Reservations + Production Orders
CREATE TABLE IF NOT EXISTS material_reservation (reservation_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, location_id TEXT NOT NULL, plan_id TEXT, plan_line_id TEXT, material_requirement_id TEXT, material_master_id TEXT NOT NULL, requirement_type TEXT NOT NULL, requested_qty NUMERIC NOT NULL, reserved_qty NUMERIC NOT NULL DEFAULT 0, released_qty NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'OPEN', notes TEXT, created_by TEXT NOT NULL, approved_by TEXT, approved_at TEXT, approval_reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_material_reservation_scope ON material_reservation(organization_id,entity_id,location_id,material_master_id,status);
CREATE TABLE IF NOT EXISTS production_order (production_order_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, location_id TEXT NOT NULL, plan_id TEXT NOT NULL, plan_line_id TEXT NOT NULL, order_no TEXT NOT NULL, product_master_id TEXT NOT NULL, planned_qty NUMERIC NOT NULL, uom TEXT NOT NULL, scheduled_start TEXT, scheduled_end TEXT, status TEXT NOT NULL DEFAULT 'DRAFT', notes TEXT, created_by TEXT NOT NULL, approved_by TEXT, approved_at TEXT, approval_reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS ux_production_order_no ON production_order(organization_id,entity_id,order_no);
CREATE TABLE IF NOT EXISTS production_order_material (order_material_id TEXT PRIMARY KEY, production_order_id TEXT NOT NULL, material_master_id TEXT NOT NULL, requirement_type TEXT NOT NULL, required_qty NUMERIC NOT NULL, reserved_qty NUMERIC NOT NULL DEFAULT 0, uom TEXT NOT NULL, notes TEXT, FOREIGN KEY(production_order_id) REFERENCES production_order(production_order_id));
